// Block (composition) — a vertical list of in-app notification cards.
// Card owns notification chrome; Stack owns grouping; this Block only arranges content and actions.
import { X } from "../components/icons";
import { Badge } from "../components/Badge";
import { Button } from "../components/Button";
import { Card, CardContent } from "../components/Card";
import { Stack } from "../layouts/Stack";
import "./NotificationList.css";

export interface NotificationListProps {
  /** Notifications to render in order. */
  items: {
    id: string;
    title: string;
    description?: string;
    timestamp?: string;
    /** Marks a notification the person has not seen yet. */
    isUnread?: boolean;
  }[];
  /** Adds a dismiss action to each notification. */
  onDismiss?: (id: string) => void;
  /** Text shown when there are no notifications. */
  emptyLabel?: string;
  className?: string;
}

export function NotificationList({
  items,
  onDismiss,
  emptyLabel = "No notifications",
  className,
}: NotificationListProps) {
  return (
    <Stack
      as="section"
      aria-label="Notifications"
      gap="small"
      className={className ? `sd-notificationlist ${className}` : "sd-notificationlist"}
    >
      {items.length === 0 ? (
        <p className="sd-notificationlist__empty sd-type-caption-medium">{emptyLabel}</p>
      ) : (
        items.map((item) => (
          <Card key={item.id} className="sd-notificationlist__item">
            <Stack direction="row" align="start" justify="between" gap="small" className="sd-notificationlist__row">
              <CardContent className="sd-notificationlist__content">
                <>
                  <Stack gap="small" className="sd-notificationlist__body">
                    {/* The name and its supporting line are ONE unit, so they group at `x-small`
                        while the row around them sits a rung looser — flat, the same 8px separated
                        the title from its description as separated it from the timestamp. */}
                    <Stack gap="x-small" className="sd-notificationlist__heading">
                      <h3 className="sd-notificationlist__title sd-type-body-medium">
                        {item.title}
                      </h3>
                      {/* One rung below the row's own title above it — CONTRASTIVE, per
                          naming-convention.md § The size axis defaults to `medium`. */}
                      {item.description && (
                        <p className="sd-notificationlist__description sd-type-body-small">
                          {item.description}
                        </p>
                      )}
                    </Stack>
                    {item.timestamp && (
                      <span className="sd-notificationlist__timestamp sd-type-caption-medium">
                        {item.timestamp}
                      </span>
                    )}
                  </Stack>
                </>
              </CardContent>
              {/* spacing: attachment — the actions act on the notification beside them */}
              {(item.isUnread || onDismiss) && (
                <Stack direction="row" align="center" gap="x-small" className="sd-notificationlist__actions">
                  {/* The word says it, so the state is not carried by colour alone. */}
                  {item.isUnread && <Badge variant="tonal">New</Badge>}
                  {onDismiss && (
                    <Button
                      type="button"
                      variant="ghost"
                      size="small"
                      isIconOnly
                      aria-label={`Dismiss ${item.title}`}
                      onPress={() => onDismiss(item.id)}
                    >
                      <X aria-hidden size="1em" />
                    </Button>
                  )}
                </Stack>
              )}
            </Stack>
          </Card>
        ))
      )}
    </Stack>
  );
}

/* NotificationList.css — .sd-notificationlist (Block)
   Arrangement only: Card owns surface styling; Stack owns flow and spacing. */
.sd-notificationlist {
  width: 100%;
}

.sd-notificationlist__content {
  flex: 1;
  min-width: 0;
}

.sd-notificationlist__title,
.sd-notificationlist__description,
.sd-notificationlist__empty {
  margin: 0;
}

.sd-notificationlist__description {
  color: var(--sd-color-text-muted);
}
